const EventEmitter = require("events");

class Counter extends EventEmitter {
  n = 0;
  inc() {
    this.n++;
    this.emit("change", this.n);
  }
}

const c = new Counter();
c.on("change", (v) => console.log(v));
c.inc(); c.inc(); c.inc();
